// Per-context JS formatting via Prettier-babel. See docs/adr/0005.
//
// Every function takes (source, options) and returns a string. If Prettier
// can't parse the input we return the source unchanged so the rest of the
// file still formats.

import prettier from 'prettier'

export async function formatExpression(source, options) {
  const wrapped = `const __edge__ = ${source.trim()};`
  const formatted = await formatJs(wrapped, options)
  if (formatted === null) return source.trim()
  return stripWrapper(formatted, /^const __edge__ =\s*/, /;?\s*$/)
}

export async function formatLet(args, options) {
  const wrapped = `let ${args.trim()};`
  const formatted = await formatJs(wrapped, options)
  if (formatted === null) return args.trim()
  return stripWrapper(formatted, /^let\s+/, /;?\s*$/)
}

export async function formatAssign(args, options) {
  const wrapped = `${args.trim()};`
  const formatted = await formatJs(wrapped, options)
  if (formatted === null) return args.trim()
  return stripWrapper(formatted, /^/, /;?\s*$/)
}

export async function formatEach(args, options) {
  const split = splitTopLevelIn(args)
  if (!split) return formatExpression(args, options)

  const left = canonicaliseEachBinding(split.left)
  const right = await formatExpression(split.right, options)

  if (!right.includes('\n')) return `${left} in ${right}`
  return `${left} in\n${indentLines(right, '  ')}`
}

export async function formatCallArgs(args, options) {
  const wrapped = `__edge__(${args.trim()});`
  const formatted = await formatJs(wrapped, options)
  if (formatted === null) return args.trim()
  return stripWrapper(formatted, /^__edge__\(\s*/, /\s*\)\s*;?\s*$/)
}

// Dispatcher used by the print phase: given a tag name + its args, returns
// the formatted args string (without the surrounding parens).
export async function formatTagArgs(name, args, options) {
  if (args === null || args.trim() === '') return ''
  const head = name.split('.')[0]
  if (head === 'each') return formatEach(args, options)
  if (head === 'let') return formatLet(args, options)
  if (head === 'assign') return formatAssign(args, options)
  if (
    head === 'if' ||
    head === 'elseif' ||
    head === 'unless' ||
    head === 'eval' ||
    head === 'inject'
  ) {
    return formatExpression(args, options)
  }
  return formatCallArgs(args, options)
}

function stripWrapper(text, leading, trailing) {
  const lines = text.split('\n')
  while (lines.length > 0 && lines[lines.length - 1].trim() === '') {
    lines.pop()
  }
  if (lines.length === 0) return ''

  lines[0] = lines[0].replace(leading, '')
  lines[lines.length - 1] = lines[lines.length - 1].replace(trailing, '')

  if (lines.length > 0 && lines[0] === '') lines.shift()
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  if (lines.length === 0) return ''

  // Re-baseline: strip the minimum leading-indent across non-blank lines
  // so the result is anchored at column 0. Relative indent between lines
  // is preserved.
  let minIndent = Infinity
  for (const l of lines) {
    if (l.trim() === '') continue
    const ws = l.match(/^\s*/)[0].length
    if (ws < minIndent) minIndent = ws
  }
  if (minIndent !== Infinity && minIndent > 0) {
    const re = new RegExp(`^ {${minIndent}}`)
    for (let i = 0; i < lines.length; i++) lines[i] = lines[i].replace(re, '')
  }
  return lines.join('\n')
}

function canonicaliseEachBinding(binding) {
  const trimmed = binding.trim()
  if (!trimmed.startsWith('(') || !trimmed.endsWith(')')) return trimmed
  return `(${trimmed
    .slice(1, -1)
    .split(',')
    .map((p) => p.trim())
    .filter(Boolean)
    .join(', ')})`
}

function indentLines(text, indent) {
  return text
    .split('\n')
    .map((l) => (l.length === 0 ? l : indent + l))
    .join('\n')
}

async function formatJs(source, options) {
  try {
    return await prettier.format(source, {
      ...passThrough(options),
      parser: 'babel',
      filepath: undefined,
    })
  } catch {
    return null
  }
}

function passThrough(options) {
  return {
    tabWidth: options.tabWidth ?? 2,
    useTabs: options.useTabs ?? false,
    printWidth: options.printWidth ?? 80,
    singleQuote: options.singleQuote ?? false,
    endOfLine: options.endOfLine ?? 'lf',
  }
}

// Splits a tag's args string on the top-level ` in ` token. Used for
// @each bindings. String/template-literal/bracket aware.
export function splitTopLevelIn(args) {
  let depth = 0
  let quote = null
  let escaped = false
  const templateStack = []

  for (let i = 0; i < args.length; i++) {
    const ch = args[i]
    if (quote) {
      if (escaped) {
        escaped = false
        continue
      }
      if (ch === '\\') {
        escaped = true
        continue
      }
      if (quote === '`' && ch === '$' && args[i + 1] === '{') {
        templateStack.push(0)
        quote = null
        i += 1
        continue
      }
      if (ch === quote) quote = null
      continue
    }
    if (ch === '"' || ch === "'" || ch === '`') {
      quote = ch
      continue
    }
    if (templateStack.length > 0) {
      if (ch === '{') {
        templateStack[templateStack.length - 1] += 1
        continue
      }
      if (ch === '}') {
        if (templateStack[templateStack.length - 1] === 0) {
          templateStack.pop()
          quote = '`'
          continue
        }
        templateStack[templateStack.length - 1] -= 1
        continue
      }
    }
    if (ch === '(' || ch === '[' || ch === '{') {
      depth += 1
      continue
    }
    if (ch === ')' || ch === ']' || ch === '}') {
      depth -= 1
      continue
    }
    if (
      depth === 0 &&
      args[i] === ' ' &&
      args[i + 1] === 'i' &&
      args[i + 2] === 'n' &&
      args[i + 3] === ' '
    ) {
      return { left: args.slice(0, i), right: args.slice(i + 4) }
    }
  }
  return null
}
